INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/1] รูปร่างและรูปทรงในธรรมชาติและสิ่งแวดล้อม', 'easy', 'mcq', 'ข้อใดอธิบายความแตกต่างระหว่าง "รูปร่าง" (Shape) และ "รูปทรง" (Form) ได้ถูกต้อง?', '["รูปร่างมี 2 มิติ (กว้างและยาว) ส่วนรูปทรงมี 3 มิติ (มีความหนาหรือความลึกเพิ่มขึ้น)","รูปร่างมี 3 มิติ ส่วนรูปทรงมี 2 มิติ","รูปร่างมีเฉพาะทรงกลมเท่านั้น","รูปร่างและรูปทรงเหมือนกันทุกประการ"]'::jsonb, 0, 'รูปร่างมี 2 มิติคือความกว้างและความยาวแบนๆ ส่วนรูปทรงมี 3 มิติคือมีมวล ปริมาตร ความหนา และความลึก'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/1] รูปทรงเรขาคณิต', 'easy', 'mcq', 'กล่องของขวัญและลูกเต๋า จัดเป็นรูปทรงชนิดใด?', '["รูปทรงกระบอก","รูปทรงลูกบาศก์ (สี่เหลี่ยมลูกบาศก์)","รูปทรงกรวย","รูปทรงกลม"]'::jsonb, 1, 'ลูกเต๋าและกล่องทรงสี่เหลี่ยมจัตุรัส มีด้านทั้ง 6 ด้านเป็นสี่เหลี่ยม เรียกว่า รูปทรงลูกบาศก์'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/2] ทัศนธาตุ: อิทธิพลของเส้น', 'medium', 'mcq', 'การวาดภาพโดยใช้ "เส้นซิกแซกหรือเส้นหยัก (Zigzag line)" ให้ความรู้สึกอย่างไรแก่ผู้ชม?', '["สงบนิ่ง ราบเรียบ","รุนแรง ตื่นเต้น เคลื่อนไหว ขัดแย้ง และน่ากลัว","นุ่มนวล อ่อนช้อย","มั่นคง แข็งแรง"]'::jsonb, 1, 'เส้นหยักหรือเส้นซิกแซก ให้ความรู้สึกตื่นเต้น อันตราย รุนแรง และการเคลื่อนไหวฉับพลัน'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/2] ทัศนธาตุ: เส้นตรงแนวนอน', 'easy', 'mcq', '"เส้นตรงแนวนอน" เช่น เส้นขอบฟ้าหรือพื้นน้ำนิ่ง ให้ความรู้สึกทางจิตวิทยาอย่างไร?', '["สงบนิ่ง ราบเรียบ กว้างขวาง และผ่อนคลาย","ตื่นเต้น หวาดเสียว","รวดเร็ว ดั่งสายฟ้า","กำลังล้มลง"]'::jsonb, 0, 'เส้นแนวนอนให้ความรู้สึกสงบ นิ่ง มั่นคง ราบเรียบ และกว้างใหญ่ ดั่งผืนน้ำและเส้นขอบฟ้า'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] วรรณะของสี: วรรณะสีอุ่น (Warm Tone)', 'easy', 'mcq', 'สีในกลุ่มใดจัดเป็นสีใน "วรรณะอุ่น" ทั้งหมด?', '["สีน้ำเงิน, สีฟ้า, สีเขียว","สีแดง, สีส้ม, สีเหลือง, สีม่วงแดง","สีขาว, สีดำ, สีเทา","สีเขียวแก่, สีคราม, สีม่วงน้ำเงิน"]'::jsonb, 1, 'วรรณะสีอุ่นให้ความรู้สึกร้อน ร่าเริง อบอุ่น ได้แก่ สีเหลือง ส้มเหลือง ส้ม แดง ม่วงแดง'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] วรรณะของสี: วรรณะสีเย็น (Cool Tone)', 'easy', 'mcq', 'สีในกลุ่มใดจัดเป็นสีใน "วรรณะเย็น" ทั้งหมด?', '["สีเขียว, สีเขียวตองอ่อน, สีน้ำเงิน, สีคราม","สีแดง, สีส้ม, สีชมพู","สีทอง, สีเงิน, สีทองแดง","สีแสด, สีน้ำตาลไหม้, สีแดงเลือดหมู"]'::jsonb, 0, 'วรรณะสีเย็นให้ความรู้สึกสงบ สดชื่น ร่มเย็น ได้แก่ สีเขียวเหลือง เขียว น้ำเงิน ม่วงน้ำเงิน'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] สีที่อยู่ได้ทั้งสองวรรณะ', 'hard', 'mcq', 'สี 2 สีใดในวงจรสี ที่สามารถอยู่ได้ทั้ง "วรรณะอุ่น" และ "วรรณะเย็น" ขึ้นอยู่กับสีที่อยู่แวดล้อม?', '["สีแดงและสีเขียว","สีเหลืองและสีม่วง","สีส้มและสีน้ำเงิน","สีดำและสีขาว"]'::jsonb, 1, 'สีเหลืองและสีม่วง เป็นสีคนกลางที่สามารถปรับเข้ากับวรรณะอุ่นหรือเย็นได้ตามสีข้างเคียงในภาพ'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] การผสมแม่สี: สีขั้นที่ 2', 'easy', 'mcq', 'เมื่อนำแม่สี "สีแดง" ผสมกับ "สีเหลือง" ในสัดส่วนเท่ากัน จะได้สีใหม่คือสีใด?', '["สีเขียว","สีส้ม","สีม่วง","สีน้ำตาล"]'::jsonb, 1, 'แม่สีขั้นที่ 1 (แดง + เหลือง) ผสมกันได้ สีส้ม (สีขั้นที่ 2)'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] แม่สีขั้นที่ 2: สีเขียว', 'easy', 'mcq', 'สีเขียวเกิดจากการผสมกันของแม่สีคู่ใด?', '["สีน้ำเงิน + สีเหลือง","สีแดง + สีน้ำเงิน","สีขาว + สีดำ","สีส้ม + สีม่วง"]'::jsonb, 0, 'สีน้ำเงินผสมกับสีเหลือง จะได้สีเขียว'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/4] แสงและเงาในภาพวาด', 'medium', 'mcq', 'เมื่อมีแสงส่องมายังวัตถุจากทางด้านบนซ้าย เงาตกทอด (Cast shadow) ของวัตถุจะปรากฏอยู่ที่ทิศทางใด?', '["ด้านบนซ้าย","ด้านล่างขวา","ด้านบนขวา","ตรงกลางวัตถุพอดี"]'::jsonb, 1, 'เงาตกทอดจะทอดยาวไปในทิศทางตรงกันข้ามกับทิศทางที่แสงส่องมาเสมอ (ตรงข้ามบนซ้ายคือล่างขวา)'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/4] พื้นผิว (Texture)', 'easy', 'mcq', 'สิ่งใดในธรรมชาติที่มีพื้นผิวสัมผัสแบบ "ขรุขระ"?', '["เปลือกหอยสังข์และเปลือกต้นไม้ใหญ่","ผิวผลแอปเปิล","กระจกเงา","ผิวน้ำนิ่ง"]'::jsonb, 0, 'เปลือกต้นไม้ใหญ่หรือเปลือกผลทุเรียน มีลักษณะพื้นผิวขรุขระอย่างชัดเจน'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/5] เทคนิคการพิมพ์ภาพ (Printmaking)', 'easy', 'mcq', 'การนำก้านกล้วย ผักบุ้ง หรือใบไม้ มาจุ่มสีแล้วกดทับลงบนกระดาษ เรียกว่าเทคนิคใด?', '["การวาดเส้น","การพิมพ์ภาพจากวัสดุธรรมชาติ","การปั้นดินน้ำมัน","การแกะสลักหิน"]'::jsonb, 1, 'เป็นการพิมพ์ภาพจากแม่พิมพ์ธรรมชาติ เช่น ก้านกล้วย ใบไม้ เปลือกหอย'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/6] งานปั้นนูนต่ำ นูนสูง และลอยตัว', 'medium', 'mcq', 'รูปปั้นอนุสาวรีย์หรือตุ๊กตาดินเผาที่สามารถเดินมองดูได้รอบทิศทาง 360 องศา จัดเป็นงานปั้นประเภทใด?', '["งานปั้นนูนต่ำ","งานปั้นนูนสูง","งานปั้นลอยตัว (Round-relief)","งานแกะสลักแบน"]'::jsonb, 2, 'งานปั้นลอยตัวเป็นงานประติมากรรมสามมิติแท้จริงที่สามารถมองเห็นได้ครบทุกด้านรอบทิศทาง'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/6] งานปั้นนูนต่ำ', 'easy', 'mcq', 'ลวดลายพระบรมรูปบน "เหรียญกษาปณ์ (เหรียญบาท, เหรียญสิบ)" จัดเป็นงานปั้นประเภทใด?', '["งานปั้นนูนต่ำ (Bas-relief)","งานปั้นนูนสูง","งานปั้นลอยตัว","งานวาดเขียน"]'::jsonb, 0, 'เหรียญกษาปณ์มีลวดลายนูนขึ้นมาจากแผ่นพื้นหลังเพียงเล็กน้อย มองเห็นด้านหน้าด้านเดียว จัดเป็นงานปั้นนูนต่ำ'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/7] การจัดองค์ประกอบภาพ: จุดเด่น (Center of Interest)', 'medium', 'mcq', 'การทำให้สิ่งสำคัญในภาพวาดมีความโดดเด่นสะดุดตาเป็นจุดแรกที่คนมอง เรียกว่าอะไร?', '["ความกลมกลืน","การสร้างจุดเด่นหรือจุดสนใจ","การระบายสีให้มืดที่สุด","การเว้นช่องว่าง"]'::jsonb, 1, 'จุดเด่นคือส่วนที่ต้องการเน้นให้ผู้ชมมองเห็นเป็นจุดแรก โดยอาจเน้นด้วยขนาด สีสัน หรือตำแหน่งในภาพ'),
('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/7] ความสมดุลในงานศิลปะ (Balance)', 'medium', 'mcq', 'ภาพวาดที่มีน้ำหนัก ซ้ายและขวาเท่ากันเหมือนส่องกระจกเงา เรียกว่าความสมดุลแบบใด?', '["ความสมดุลแบบสองข้างเท่ากัน (Symmetrical Balance)","ความสมดุลแบบสองข้างไม่เท่ากัน","ความขัดแย้ง","ความกลมกลืน"]'::jsonb, 0, 'ความสมดุลแบบซ้ายขวาเหมือนกันทุกประการ (สมมาตร) ให้ความรู้สึกมั่นคง เป็นทางการ สงบ'),
('ศิลปะ', 'ป.4', '[ศ 1.2 ป.4/1] ศิลปะและภูมิปัญญาท้องถิ่น: ผ้ามัดหมี่', 'medium', 'mcq', '"ผ้าไหมมัดหมี่" เป็นงานหัตถกรรมทัศนศิลป์พื้นบ้านที่มีชื่อเสียงโดดเด่นของภาคใด?', '["ภาคใต้","ภาคกลาง","ภาคตะวันออกเฉียงเหนือ (อีสาน)","ภาคตะวันออก"]'::jsonb, 2, 'การมัดหมี่ทอผ้าไหมลายโบราณ (เช่น ลายหมี่ขอนารี ลายนาค) เป็นเอกลักษณ์อันวิจิตรงดงามของภาคอีสาน'),
('ศิลปะ', 'ป.4', '[ศ 1.2 ป.4/1] เครื่องปั้นดินเผาเกาะเกร็ด', 'medium', 'mcq', 'เครื่องปั้นดินเผาดินเผาเนื้อละเอียดแกะสลักลวดลายวิจิตรที่ "เกาะเกร็ด" จังหวัดนนทบุรี เป็นภูมิปัญญาของชาวไทยเชื้อสายใด?', '["ไทยวน","ไทยรามัญ (มอญ)","ไทยพวน","ไทยลื้อ"]'::jsonb, 1, 'เกาะเกร็ดมีชื่อเสียงด้านเครื่องปั้นดินเผาดินแดงแกะสลักลวดลายประณีต สืบทอดจากชาวไทยรามัญ (มอญ)'),
('ศิลปะ', 'ป.4', '[ศ 1.2 ป.4/2] จิตรกรรมฝาผนังวัดไทย', 'easy', 'mcq', 'ภาพจิตรกรรมฝาผนังภายในพระอุโบสถวัดไทย นิยมเขียนเล่าเรื่องราวเกี่ยวกับสิ่งใดเป็นส่วนใหญ่?', '["ประวัติศาสตร์สงครามโลก","พุทธประวัติและทศชาติชาดก","ภาพสัตว์ประหลาดแฟนตาซี","ภาพธรรมชาติเมืองหนาว"]'::jsonb, 1, 'จิตรกรรมฝาผนังวัดไทยเน้นบอกเล่าเรื่องพุทธประวัติ ชาดก และนรกสวรรค์เพื่อสอนศีลธรรมแก่พุทธศาสนิกชน'),
('ศิลปะ', 'ป.4', '[ศ 1.2 ป.4/2] การดูแลและทำความสะอาดอุปกรณ์ศิลปะ', 'easy', 'mcq', 'หลังจากใช้ "พู่กันระบายสีน้ำ" เสร็จแล้ว ควรทำความสะอาดและเก็บรักษาอย่างไร?', '["แช่พู่กันทิ้งไว้ในแก้วน้ำข้ามคืน","ล้างขนพู่กันในน้ำสะอาดจนหมดคราบสี ลูบปลายขนให้แหลมมน แล้ววางผึ่งลมให้แห้ง","ใช้ไฟรนขนพู่กันให้แห้งเร็ว","ทิ้งถังขยะแล้วซื้อใหม่ทุกครั้ง"]'::jsonb, 1, 'การล้างคราบสีออกให้หมด ลูบปลายขนให้เข้าทรง แล้วผึ่งให้แห้ง ช่วยยืดอายุการใช้งานของพู่กัน'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/1] คุณสมบัติของเสียงดนตรี', 'easy', 'mcq', 'คุณสมบัติของเสียงในข้อใดหมายถึง "ความถี่ของเสียงที่มีระดับเสียงสูงหรือต่ำ"?', '["ระดับเสียง (Pitch)","ความดัง-เบา (Dynamic)","ความสั้น-ยาว (Duration)","สีสันของเสียง (Timbre)"]'::jsonb, 0, 'ระดับเสียง (Pitch) คือความสูง-ต่ำของเสียงดนตรี เกิดจากความถี่ในการสั่นสะเทือนของแหล่งกำเนิดเสียง'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/2] สัญลักษณ์ทางดนตรี: บรรทัด 5 เส้น', 'easy', 'mcq', 'บรรทัด 5 เส้น (Staff) ที่ใช้บันทึกโน้ตดนตรีสากล ประกอบด้วยเส้นกี่เส้นและช่องกี่ช่อง?', '["4 เส้น 3 ช่อง","5 เส้น 4 ช่อง","6 เส้น 5 ช่อง","5 เส้น 5 ช่อง"]'::jsonb, 1, 'บรรทัด 5 เส้น มีเส้นแนวนอนขนานกัน 5 เส้น และเกิดช่องว่างระหว่างเส้น 4 ช่อง'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/2] กุญแจประจำหลัก: กุญแจซอล (G Clef)', 'medium', 'mcq', 'หัวของ "กุญแจซอล (Treble Clef)" เริ่มต้นเขียนวนคาบอยู่บนเส้นใดของบรรทัด 5 เส้น?', '["เส้นที่ 1","เส้นที่ 2","เส้นที่ 3","เส้นที่ 4"]'::jsonb, 1, 'กุญแจซอลเริ่มเขียนวนที่เส้นที่ 2 นับจากล่างขึ้นบน ทำให้โน้ตที่คาบเส้นที่ 2 มีเสียงเป็นเสียง "ซอล (G)" เสมอ'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/2] อัตราความยาวของตัวโน้ตสากล', 'medium', 'mcq', 'ในจังหวะ 4/4 "โน้ตตัวกลม (Whole note)" มีอัตราความยาวเท่ากับกี่จังหวะ?', '["1 จังหวะ","2 จังหวะ","3 จังหวะ","4 จังหวะ"]'::jsonb, 3, 'โน้ตตัวกลมมีค่ายาวที่สุดเท่ากับ 4 จังหวะ (ตัวขาว = 2 จังหวะ, ตัวดำ = 1 จังหวะ, ตัวเขบ็ต 1 ชั้น = ครึ่งจังหวะ)'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] ประเภทเครื่องดนตรีไทย: เครื่องดีด', 'easy', 'mcq', 'เครื่องดนตรีไทยในข้อใดจัดเป็น "เครื่องดีด"?', '["จะเข้ และ ซึง","ซอด้วง และ ซออู้","ระนาดเอก และ ฆ้องวง","ขลุ่ยเพียงออ และ ปี่ใน"]'::jsonb, 0, 'จะเข้และซึงเป็นเครื่องสายที่บรรเลงโดยใช้นิ้วหรือไม้ดีดสายให้เกิดเสียง'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] ประเภทเครื่องดนตรีไทย: เครื่องสี', 'easy', 'mcq', 'เครื่องดนตรีไทยที่ใช้คันชักถูกับสายให้เกิดเสียง จัดเป็นเครื่องดนตรีประเภทใด?', '["เครื่องดีด","เครื่องสี (เช่น ซอด้วง ซออู้ ซอสามสาย)","เครื่องตี","เครื่องเป่า"]'::jsonb, 1, 'เครื่องสีใช้คันชักที่มีหางม้าสีเสียดสีกับสาย เกิดการสั่นสะเทือนเป็นเสียงกังวาน'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] ประเภทเครื่องดนตรีไทย: เครื่องตี', 'easy', 'mcq', 'เครื่องดนตรีไทยข้อใดเป็นเครื่องตีที่ทำด้วยไม้เนื้อแข็ง มีผืนระนาดแขวนบนราง?', '["ระนาดเอก","ฆ้องวงใหญ่","กลองแขก","ฉิ่ง"]'::jsonb, 0, 'ระนาดเอกมีลูกระนาดทำจากไม้ไผ่บงหรือไม้ชิงชันร้อยเป็นผืนแขวนไว้บนรางไม้รูปทรงคล้ายเรือสำเภา'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] เครื่องดนตรีกำกับจังหวะสำคัญ', 'easy', 'mcq', 'เครื่องดนตรีไทยชิ้นใดมีหน้าที่สำคัญที่สุดในการ "กำกับจังหวะหน้าทับและจังหวะหลัก" ของวงดนตรีไทย?', '["ฉิ่ง","ขลุ่ย","ซออู้","ระนาดเอก"]'::jsonb, 0, 'ฉิ่งทำหน้าที่ควบคุมจังหวะช้า-เร็ว (เสียงฉิ่ง-ฉับ) ถือเป็นหัวใจในการกำกับจังหวะของวงดนตรีไทย'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] ประเภทเครื่องดนตรีสากล: เครื่องสาย (Strings)', 'easy', 'mcq', 'เครื่องดนตรีสากลในข้อใดจัดเป็นเครื่องดนตรีประเภทเครื่องสายทั้งหมด?', '["ไวโอลิน, กีตาร์, เชลโล, ฮาร์ป","ทรัมเป็ต, แซกโซโฟน, ฟลูต","กลองชุด, ไซโลโฟน","เปียโน, คีย์บอร์ด"]'::jsonb, 0, 'ไวโอลิน กีตาร์ เชลโล ฮาร์ป มีสายขึงตึงและทำให้เกิดเสียงด้วยการดีดหรือสี'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] เครื่องเป่าลมทองเหลือง (Brass)', 'medium', 'mcq', 'เครื่องดนตรีสากลข้อใดจัดเป็น "เครื่องเป่าลมทองเหลือง"?', '["ฟลูต (Flute)","คลาริเน็ต (Clarinet)","ทรัมเป็ต (Trumpet)","โอโบ (Oboe)"]'::jsonb, 2, 'ทรัมเป็ต ทรอมโบน ทูบา ทำจากโลหะทองเหลือง เป่าผ่านปากเป่ารูปถ้วย จัดเป็นกลุ่ม Brass Instruments'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/4] การขับร้องเพลงและการหายใจ', 'easy', 'mcq', 'การหายใจที่ถูกต้องสำหรับการขับร้องเพลงเพื่อให้มีพลังเสียงกังวานและร้องได้ยาว ควรใช้การหายใจแบบใด?', '["หายใจเข้าทางปากตื้นๆ ที่หน้าอก","หายใจเข้าลึกๆ โดยใช้กล้ามเนื้อกระบังลม (ท้องขยายเมื่อหายใจเข้า)","กลั้นหายใจตลอดเวลา","หายใจหอบเร็วๆ"]'::jsonb, 1, 'การหายใจด้วยกระบังลม (Diaphragmatic breathing) ช่วยให้กักเก็บลมได้มากและควบคุมลมหายใจออกขณะร้องเพลงได้อย่างสม่ำเสมอ'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/4] การขับร้องเพลงไทย: การเอื้อน', 'medium', 'mcq', 'การเปล่งเสียงทำนองโดยไม่เปล่งเสียงพยัญชนะหรือคำร้อง ออกเป็นเสียง เออ... เอย... ในเพลงไทย เรียกว่าอะไร?', '["การเอื้อน","การแร็ป","การประสานเสียง","การหวีดเสียง"]'::jsonb, 0, 'การเอื้อนเสียงเป็นเอกลักษณ์เฉพาะของเพลงไทยเดิม เพื่อทอดทำนองให้ไพเราะนุ่มนวลตามเสียงดนตรี'),
('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/1] วงดนตรีไทย: วงปี่พาทย์', 'medium', 'mcq', 'วงดนตรีไทยที่ประกอบด้วยเครื่องตีเป็นหลัก (ระนาดเอก ระนาดทุ้ม ฆ้องวง กลองทัด ตะโพน) และเครื่องเป่า (ปี่ใน) เรียกว่าวงอะไร?', '["วงเครื่องสาย","วงปี่พาทย์","วงมโหรี","วงสะล้อซอซึง"]'::jsonb, 1, 'วงปี่พาทย์เป็นวงที่เน้นเครื่องตีประเภทไม้ โลหะ หนัง ร่วมกับปี่ มีเสียงดังกังวาน นิยมบรรเลงในพิธีกรรมและโขนละคร'),
('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/1] วงดนตรีพื้นบ้านภาคอีสาน: วงโปงลาง', 'easy', 'mcq', 'เครื่องดนตรีที่ทำจากท่อนไม้เนื้อแข็งแขวนเรียงเป็นผืน ตีด้วยไม้ ให้เสียงไพเราะสนุกสนานในภาคอีสานคือข้อใด?', '["โปงลาง","แคน","พิณ","โหวต"]'::jsonb, 0, 'โปงลางทำจากท่อนไม้มะหาดหรือไม้หมากเหลื่อม เป็นเครื่องดนตรีเอกลักษณ์ของดนตรีพื้นบ้านอีสาน'),
('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/1] เครื่องดนตรีพื้นบ้าน: แคน', 'easy', 'mcq', '"แคน" ทำมาจากวัสดุธรรมชาติใดเป็นหลัก?', '["ลำไม้ไผ่ (ไม้กู่แคน)","กระบอกกะลามะพร้าว","เขาสัตว์","ดินเหนียวตากแห้ง"]'::jsonb, 0, 'แคนทำจากไม้ซางหรือไม้กู่แคน มีลิ้นโลหะอยู่ภายใน เป่าได้ทั้งดูดลมเข้าและเป่าลมออก'),
('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/1] วงดนตรีพื้นเมืองภาคเหนือ: สะล้อ ซอ ซึง', 'medium', 'mcq', 'เครื่องดนตรีพื้นเมืองภาคเหนือชนิดใดจัดเป็น "เครื่องสี"?', '["ซึง","สะล้อ","กลองสะบัดชัย","ปี่จุม"]'::jsonb, 1, 'สะล้อเป็นเครื่องสี 2 สายหรือ 3 สาย กะโหลกทำด้วยกะลามะพร้าว ให้เสียงหวานซึ้งตามแบบวัฒนธรรมล้านนา'),
('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/2] เพลงพระราชนิพนธ์', 'easy', 'mcq', 'เพลงพระราชนิพนธ์ในรัชกาลที่ 9 ที่พระราชทานให้เป็นเพลงประจำวันขึ้นปีใหม่ คือเพลงใด?', '["เพลงสายฝน","เพลงพรปีใหม่","เพลงใกล้รุ่ง","เพลงชะตาชีวิต"]'::jsonb, 1, 'เพลงพระราชนิพนธ์ "พรปีใหม่" ทรงพระราชนิพนธ์ขึ้นใน พ.ศ. 2494 เพื่อพระราชทานความสุขแก่ปวงชนชาวไทยในวันปีใหม่'),
('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/2] มารยาทในการฟังดนตรี', 'easy', 'mcq', 'มารยาทที่ถูกต้องในการชมการแสดงดนตรีในโรงละครคือข้อใด?', '["ส่งเสียงตะโกนคุยโทรศัพท์ตลอดเวลา","ปรบมือเมื่อจบแต่ละบทเพลง และไม่ลุกเดินไปมาขณะนักดนตรีกำลังบรรเลง","นำอาหารกลิ่นแรงเข้าไปรับประทาน","ใช้นกหวีดเป่าแข่งกับดนตรี"]'::jsonb, 1, 'การปรบมือให้เกียรตินักแสดงเมื่อเพลงจบ และการรักษาความเงียบระหว่างการแสดง เป็นมารยาทสากลของการฟังดนตรี'),
('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/1] สัญลักษณ์ไดนามิก (Dynamic): เปียโน และ ฟอร์เต', 'hard', 'mcq', 'สัญลักษณ์ตัวย่อ "p" (piano) และ "f" (forte) ในโน้ตเพลง หมายถึงระดับความดัง-เบาอย่างไรตามลำดับ?', '["ดังมาก และ เบามาก","เบา (Soft) และ ดัง (Loud)","เร็ว และ ช้า","หยุดเสียง และ เริ่มเสียง"]'::jsonb, 1, 'p (piano) หมายถึงให้เล่นเสียงเบา ส่วน f (forte) หมายถึงให้เล่นเสียงดัง'),
('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/2] การอนุรักษ์ดนตรีไทย', 'easy', 'mcq', 'เยาวชนไทยสามารถมีส่วนร่วมในการอนุรักษ์ดนตรีไทยได้อย่างไร?', '["ฝึกหัดเล่นเครื่องดนตรีไทยและสนับสนุนชื่นชมบทเพลงไทยเดิม","ช่วยกันเก็บเครื่องดนตรีไทยไว้ในตู้กระจกห้ามใครแตะต้อง","ยกเลิกการสอนดนตรีไทยในโรงเรียน","ดัดแปลงให้เปลี่ยนเป็นดนตรีร็อกทั้งหมด"]'::jsonb, 0, 'การเรียนรู้ ฝึกฝน และร่วมสืบสานการแสดงดนตรีไทยในชีวิตประจำวัน ช่วยให้มรดกทางดนตรีไทยคงอยู่สืบไป'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] นาฏยศัพท์: การจีบ', 'easy', 'mcq', 'การปฏิบัติท่า "จีบ" ในนาฏศิลป์ไทย ใช้นิ้วใดจรดกับนิ้วใด?', '["นิ้วชี้จรดกับนิ้วกลาง","ปลายนิ้วหัวแม่มือจรดกับข้อแรกของปลายนิ้วชี้ แล้วกรีดนิ้วที่เหลือออก","นิ้วก้อยจรดกับนิ้วโป้ง","กำนิ้วทั้ง 5 เข้าหาฝ่ามือ"]'::jsonb, 1, 'การจีบ ใช้นิ้วหัวแม่มือจรดข้อแรกของนิ้วชี้ นิ้วกลาง นาง ก้อย กรีดเหยียดตึงออกเป็นรูปพัด และหักข้อมือเข้าหาแขน'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] จีบหงาย และ จีบคว่ำ', 'easy', 'mcq', 'การทำท่าจีบโดย "หงายฝ่ามือขึ้น ให้ปลายนิ้วชี้ชี้ขึ้นด้านบน และหักข้อมือเข้าหาลำแขน" เรียกว่าท่าใด?', '["จีบคว่ำ","จีบหงาย","จีบส่งหลัง","จีบปรกหน้า"]'::jsonb, 1, 'จีบหงาย คือการหงายฝ่ามือขึ้น ปลายนิ้วที่จีบชี้ขึ้นข้างบน หักข้อมือเข้าหาลำแขน'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] นาฏยศัพท์: การตั้งวงบน', 'medium', 'mcq', 'การ "ตั้งวงบน" ของตัวพระ (ชาย) และตัวนาง (หญิง) ปลายนิ้วมือจะอยู่ในระดับใดตามลำดับ?', '["ตัวพระระดับแง่ศีรษะ, ตัวนางระดับหางคิ้ว","ตัวพระระดับอก, ตัวนางระดับปาก","ตัวพระระดับเอว, ตัวนางระดับหัวเข่า","ตัวพระระดับปลายคาง, ตัวนางระดับหน้าผาก"]'::jsonb, 0, 'ตัวพระตั้งวงบนปลายนิ้วอยู่ระดับแง่ศีรษะ (กันวงออกกว้าง) ส่วนตัวนางปลายนิ้วอยู่ระดับหางคิ้ว (วงแคบกว่า)'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] การตั้งวงกลางและวงล่าง', 'easy', 'mcq', 'การ "ตั้งวงล่าง" ปลายนิ้วมือทั้งสี่จะทอดโค้งอยู่ระดับใดของร่างกาย?', '["ระดับสายตา","ระดับอก","ระดับหัวเข็มขัดหรือสะดือ","ระดับปลายเท้า"]'::jsonb, 2, 'ตั้งวงล่าง ทอดลำแขนลงข้างล่าง โค้งลำแขน ปลายนิ้วอยู่ระดับหัวเข็มขัดหรือสะดือ หักข้อมือขึ้น'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] นาฏยศัพท์ส่วนเท้า: การก้าวหน้า', 'medium', 'mcq', 'การปฏิบัติท่า "ก้าวหน้า" เท้าที่ก้าวไปข้างหน้าต้องวางส้นเท้าและปลายเท้าอย่างไร?', '["วางปลายเท้าลงก่อน","ก้าวเท้าเฉียงไปข้างหน้า วางส้นเท้าลงก่อน ปลายเท้ายกเชิดขึ้น แล้วถ่ายน้ำหนักตัวไปเท้าหน้า","กระโดดลงด้วยเท้าคู่","ลากปลายเท้าไปข้างหลัง"]'::jsonb, 1, 'การก้าวหน้าในนาฏศิลป์ไทย ต้องเปิดปลายเท้า วางส้นเท้าลงก่อน ปลายเท้าเชิดขึ้น จากนั้นจึงวางเต็มฝ่าเท้าถ่ายน้ำหนัก'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/2] ภาษาท่าทางนาฏศิลป์: ภาษาท่าเลียนแบบอารมณ์', 'easy', 'mcq', 'การใช้มือซ้ายทาบที่บริเวณหน้าอก (ระดับหัวใจ) หมายถึงภาษาท่าสื่อความรู้สึกใด?', '["ท่ารัก หรือ ท่าดีใจ","ท่าโกรธ","ท่าร้องไห้เสียใจ","ท่ากลัว"]'::jsonb, 0, 'การทาบมือที่หน้าอก เป็นภาษาท่าสื่อความหมายถึง ความรัก ความปลื้มใจ หรือความจริงใจในใจ'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/2] ภาษาท่า: ท่าปฏิเสธ', 'easy', 'mcq', 'การตั้งมือข้างหนึ่งระดับอกแล้วส่ายข้อมือไปมาเล็กน้อย เป็นภาษาท่าสื่อความหมายว่าอะไร?', '["ท่าเรียกมาหา","ท่าปฏิเสธ (ไม่เอา/ไม่ใช่)","ท่ายินดีต้อนรับ","ท่าหลับนอน"]'::jsonb, 1, 'การตั้งมือระดับอกแล้วส่ายปลายนิ้วไปมาเบาๆ สื่อความหมายถึงการปฏิเสธ หรือคำว่า "ไม่"'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/2] ภาษาท่า: ท่าอาย', 'medium', 'mcq', 'ภาษาท่า "อาย" ในนาฏศิลป์ไทย มีลักษณะการปฏิบัติอย่างไร?', '["ใช้ฝ่ามือแตะข้างแก้มใกล้ขมับ เอียงศีรษะ หลบสายตา","กระทืบเท้าเสียงดัง","เอามือปิดตาสองข้าง","อ้าปากหัวเราะกว้าง"]'::jsonb, 0, 'ท่าอาย ใช้ฝ่ามือแตะข้างแก้มใกล้ขมับ เอียงศีรษะไปข้างตรงข้ามกับมือ ชายตาลงเล็กน้อยเพื่อแสดงความเขินอาย'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/2] ภาษาท่า: ท่าโกรธ', 'medium', 'mcq', 'การใช้ฝ่ามือถูกระทบหลังใบหูแล้วกระชากมือลง พร้อมกระทืบเท้า เป็นภาษาท่าใด?', '["ท่าโกรธ","ท่าเสียใจ","ท่ากราบไหว้","ท่ารักใคร่"]'::jsonb, 0, 'ใช้ฝ่ามือถูใต้ใบหูแล้วกระชากมือลง สื่อถึงอารมณ์โกรธจัดหรือแค้นเคือง'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/3] รำวงมาตรฐาน: เพลงงามแสงเดือน', 'easy', 'mcq', 'เพลงรำวงมาตรฐานเพลงแรก "เพลงงามแสงเดือน" ใช้ท่ารำมาตรฐานท่าใด?', '["ท่าสอดสร้อยมาลา","ท่าชักแป้งผัดหน้า","ท่าแขกเต้าเข้ารัง","ท่ายั่ว"]'::jsonb, 0, 'เพลงงามแสงเดือนใช้ท่ารำ "สอดสร้อยมาลา"'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/3] รำวงมาตรฐาน: เพลงชาวไทย', 'medium', 'mcq', 'เพลงรำวงมาตรฐาน "เพลงชาวไทย" ใช้ท่ารำใดในการแสดง?', '["ท่าชักแป้งผัดหน้า","ท่าสอดสร้อยมาลาแปลง","ท่าพวงมาลัย","ท่าจันทร์ทรงกลด"]'::jsonb, 0, 'เพลงชาวไทยใช้ท่ารำ "ชักแป้งผัดหน้า"'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/3] กำเนิดรำวงมาตรฐาน', 'hard', 'mcq', 'รำวงมาตรฐานได้รับการปรับปรุงและพัฒนามาจากการละเล่นพื้นบ้านชนิดใด?', '["รำโทน","เพลงเรือ","เต้นกำรำเคียว","ลำตัด"]'::jsonb, 0, 'รำวงมาตรฐานพัฒนามาจาก "รำโทน" ในช่วงสงครามโลกครั้งที่ 2 โดยกรมศิลปากรปรับปรุงท่ารำและบทเพลงให้เป็นแบบแผนสากล'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/4] การแสดงพื้นเมือง 4 ภาค: ภาคเหนือ', 'easy', 'mcq', 'การแสดงนาฏศิลป์พื้นเมืองภาคเหนือที่มีท่วงท่านุ่มนวล อ่อนช้อย อิงวัฒนธรรมล้านนา คือข้อใด?', '["ฟ้อนเล็บ, ฟ้อนเทียน","เซิ้งกระติบข้าว","ระบำรองเง็ง","เต้นกำรำเคียว"]'::jsonb, 0, 'ฟ้อนเล็บและฟ้อนเทียนเป็นการแสดงพื้นเมืองภาคเหนือที่ผู้แสดงสวมเล็บยาวสีทอง ร่ายรำอย่างอ่อนช้อยงดงาม'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/4] การแสดงพื้นเมือง: ภาคอีสาน', 'easy', 'mcq', 'การแสดงพื้นเมืองภาคอีสานที่มีลีลากระฉับกระเฉง สนุกสนาน คล่องแคล่ว เช่น "เซิ้งกระติบข้าว" สื่อถึงวิถีชีวิตใด?', '["การเดินทางออกไปหาปลาในทะเล","การนำข้าวเหนียวใส่กระติบไปส่งให้คนในครอบครัวที่ทำนา","การรบกับข้าศึก","การขึ้นเขาเก็บใบชา"]'::jsonb, 1, 'เซิ้งกระติบข้าวสะท้อนวิถีชีวิตของหญิงสาวอีสานที่สะพายกระติบข้าวเหนียวไปส่งให้สามีหรือญาติที่ทำงานในท้องนา'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/4] การแสดงพื้นเมือง: ภาคใต้', 'medium', 'mcq', 'การแสดงพื้นเมืองภาคใต้ที่มีการแต่งกายด้วยชุดลูกปัดหลากสี สวมเทริดบนศีรษะ ดัดนิ้วมืออ่อนช้อย คือการแสดงใด?', '["โนรา (มโนราห์)","เซิ้งสวิง","รำเถิดเทิง","ฟ้อนสาวไหม"]'::jsonb, 0, 'โนราเป็นการแสดงนาฏศิลป์ชั้นสูงของภาคใต้ที่ได้รับการขึ้นทะเบียนเป็นมรดกภูมิปัญญาทางวัฒนธรรมที่จับต้องไม่ได้ของยูเนสโก'),
('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/4] การแสดงพื้นเมือง: ภาคกลาง', 'easy', 'mcq', 'การแสดง "เต้นกำรำเคียว" ของภาคกลาง สะท้อนถึงวิถีชีวิตอาชีพใด?', '["ชาวสวนผลไม้","ชาวนาในฤดูเกี่ยวข้าว","ชาวประมง","ช่างปั้นหม้อ"]'::jsonb, 1, 'เต้นกำรำเคียวเป็นการละเล่นร้องรำแก้กันระหว่างหนุ่มสาวชาวนาในฤดูกาลลงแขกเกี่ยวข้าว'),
('ศิลปะ', 'ป.4', '[ศ 3.2 ป.4/1] โขนไทยและวรรณคดี', 'medium', 'mcq', 'การแสดง "โขน" ของไทย นิยมแสดงเรื่องราวจากวรรณคดีเรื่องใดเรื่องเดียวเท่านั้น?', '["ขุนช้างขุนแผน","รามเกียรติ์","อิเหนา","พระอภัยมณี"]'::jsonb, 1, 'โขนเป็นการแสดงนาฏศิลป์ชั้นสูงที่สวมหน้าโขนหัวโขน บรรเลงด้วยวงปี่พาทย์ และแสดงเฉพาะเรื่อง "รามเกียรติ์"'),
('ศิลปะ', 'ป.4', '[ศ 3.2 ป.4/1] ตัวละครในโขน: ตัวยักษ์', 'easy', 'mcq', 'ตัวละครยักษ์เอกในเรื่องรามเกียรติ์ที่มี 10 หน้า 20 มือ และมีกายสีเขียว คือตัวละครใด?', '["หนุมาน","ทศกัณฐ์","พระราม","สุครีพ"]'::jsonb, 1, 'ทศกัณฐ์ พญายักษ์แห่งกรุงลงกา มีกายสีเขียว 10 หน้า 20 มือ'),
('ศิลปะ', 'ป.4', '[ศ 3.2 ป.4/2] มารยาทในการชมการแสดงนาฏศิลป์', 'easy', 'mcq', 'ข้อใดเป็นข้อปฏิบัติที่ดีในการชมการแสดงรำไทยหรือโขน?', '["ลุกขึ้นเต้นเลียนแบบนักแสดงหน้าเวที","แต่งกายสุภาพ ให้เกียรติสถานที่ และปรบมือเมื่อเปิดม่านและหลังจบการแสดง","ใช้แฟลชถ่ายรูปใส่หน้านักแสดงตลอดเวลา","ส่งเสียงตะโกนคุยกับเพื่อนข้างๆ"]'::jsonb, 1, 'การแต่งกายสุภาพ สำรวมกิริยา และปรบมือให้กำลังใจนักแสดงหลังจบการแสดง ถือเป็นมารยาทที่ดีของผู้เข้าชม'),
('ศิลปะ', 'ป.4', '[ศ 3.2 ป.4/2] คุณค่าของนาฏศิลป์ไทย', 'easy', 'mcq', 'นาฏศิลป์ไทยมีคุณค่าและสะท้อนเอกลักษณ์ของชาติไทยอย่างไร?', '["เป็นเพียงการออกกำลังกายยามว่าง","สะท้อนถึงขนบธรรมเนียม ความประณีตงดงามของภาษา วรรณคดี และภูมิปัญญาไทยที่สั่งสมมาอย่างยาวนาน","ช่วยให้มีชื่อเสียงทางธุรกิจ","ทำให้ต่างชาติเกรงกลัวอำนาจ"]'::jsonb, 1, 'นาฏศิลป์ไทยเป็นมรดกทางวัฒนธรรมอันทรงคุณค่า ผสมผสานดนตรี วรรณคดี เครื่องแต่งกายวิจิตร และกิริยามารยาทอันงดงามของไทย');
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active)
